```yaml
name: Workflow Approval
on:
  pull_request_target:
    types: [labeled, synchronize]
    branches:
      - main
      - release-**
permissions:
  contents: read
jobs:
  approve-workflow:
    if: github.event.label.name == 'ok-to-test' || github.event_name == 'pull_request_target'
    runs-on: ubuntu-latest
    permissions:
      actions: write
    steps:
      - name: Check if contributor is returning
        id: check_contributor
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: pullRequest } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.pull_request.number
            });

            const { data: commits } = await github.rest.pulls.listCommits({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.pull_request.number
            });

            const author = pullRequest.user.login;

            // Get the contributor's PR history
            const { data: prs } = await github.rest.search.issuesAndPullRequests({
              q: `author:${author} repo:${context.repo.owner}/${context.repo.repo}`,
              sort: 'created',
              order: 'asc',
              per_page: 100
            });

            // Count PRs by this author
            const prCount = prs.items.filter(item => item.pull_request).length;

            // If contributor has 1 or fewer PRs, they're a first-time contributor
            const isFirstTime = prCount <= 1;

            // If we're dealing with a synchronize event, check if it's a returning contributor
            const isSynchronizeEvent = context.eventName === 'pull_request_target' && context.payload.action === 'synchronize';

            // If it's a first-time contributor or a returning contributor with ok-to-test label
            const shouldApprove = isFirstTime || (isSynchronizeEvent && !isFirstTime);

            core.setOutput('should_approve', shouldApprove.toString());
            core.setOutput('is_first_time', isFirstTime.toString());

      - name: Approve workflow runs
        if: steps.check_contributor.outputs.should_approve == 'true'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: workflows } = await github.rest.actions.listWorkflowRuns({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_request: context.payload.pull_request.number
            });

            for (const workflow of workflows.workflow_runs) {
              if (workflow.status === 'queued' && workflow.conclusion === null) {
                await github.rest.actions.approveWorkflowRun({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  run_id: workflow.id
                });
              }
            }
